const items = $input.all();
const resultados = [];

// Manejar si viene envuelto en "data" (estándar de JSON:API)
let jobs = [];
if (items[0].json && Array.isArray(items[0].json.data)) {
  jobs = items[0].json.data;
} else {
  jobs = items.map(i => i.json);
}

for (const job of jobs) {
  const attr = job.attributes || {};

  // 1. URL GARANTIZADA
  const url = `https://www.getonbrd.com/jobs/${job.id}`;

  // 2. DESCRIPCIÓN EXACTA
  const partesDesc = [
    attr.description_headline,
    attr.description,
    attr.projects,
    attr.functions_headline,
    attr.functions,
    attr.benefits_headline,
    attr.benefits,
    attr.desirable_headline,
    attr.desirable
  ].filter(Boolean).join(' '); 

  const descripcionLimpia = partesDesc.replace(/<[^>]*>?/gm, ' ').replace(/\s+/g, ' ').trim();

  // 3. UBICACIÓN DINÁMICA (Con el salvavidas de la URL que sugeriste)
  let ubicacion = '';

  let pais = '';
  if (attr.country) {
    pais = typeof attr.country === 'object' ? attr.country.name : attr.country;
  }

  // A. Primero intentamos lo oficial (si es remoto o trae país)
  if (attr.remote || attr.remote_zone) {
    ubicacion = attr.remote_zone ? `Remote (${attr.remote_zone})` : 'Remote';
  } else if (pais) {
    ubicacion = pais;
  } else {
    // B. PLAN DE RESCATE: Buscar la ciudad en la URL (job.id)
    const idStr = (job.id || '').toLowerCase();

    if (idStr.includes('bogota')) ubicacion = 'Bogotá, Colombia';
    else if (idStr.includes('medellin')) ubicacion = 'Medellín, Colombia';
    else if (idStr.includes('santiago')) ubicacion = 'Santiago, Chile';
    else if (idStr.includes('lima')) ubicacion = 'Lima, Perú';
    else if (idStr.includes('buenos-aires')) ubicacion = 'Buenos Aires, Argentina';
    else if (idStr.includes('mexico') || idStr.includes('cdmx')) ubicacion = 'México';
    else if (idStr.includes('montevideo')) ubicacion = 'Montevideo, Uruguay';
    else if (idStr.includes('quito')) ubicacion = 'Quito, Ecuador';
    else if (idStr.includes('remote') || idStr.includes('remoto')) ubicacion = 'Remote';
    else ubicacion = 'No especificada';
  }

  // 4. EMPRESA
  let empresa = 'Confidencial';
  if (job.relationships?.company?.data?.id) {
     empresa = job.relationships.company.data.id.replace(/-/g, ' ').replace(/\b\w/g, l => l.toUpperCase());
  } else if (attr.company?.data?.attributes?.name) {
     empresa = attr.company.data.attributes.name;
  }

  resultados.push({
    json: {
      id: job.id,
      fuente: 'GetOnBoard',
      titulo: attr.title || 'Sin título',
      empresa: empresa,
      url: url,
      ubicacion: ubicacion,
      descripcionLimpia: descripcionLimpia
    }
  });
}

return resultados;

const items = $input.all();
const nuevosJobs = [];

const jobUrlRegex = /https:\/\/www\.linkedin\.com\/(?:comm\/)?jobs\/view\/\d+[^\s]*/i;

const lineasIgnoradas = new Set([
  'Solicitar con perfil y CV',
  'Solicitud sencilla'
]);

for (const item of items) {
  const texto = String(
    item.json.textPlain || item.json.snippet || ''
  ).replace(/\r/g, '');

  const msgId = item.json.id || Date.now();
  const lineas = texto
    .split('\n')
    .map(linea => linea.trim())
    .filter(Boolean);

  for (let i = 0; i < lineas.length; i++) {
    const coincidencia = lineas[i].match(jobUrlRegex);

    if (!coincidencia) {
      continue;
    }

    const url = coincidencia[0];

    const contexto = lineas
      .slice(Math.max(0, i - 6), i)
      .filter(linea =>
        !linea.startsWith('Ver anuncio de empleo') &&
        !lineasIgnoradas.has(linea) &&
        !/^[-]+$/.test(linea)
      );

    if (contexto.length < 3) {
      continue;
    }

    let ubicacion = contexto[contexto.length - 1];
    const empresa = contexto[contexto.length - 2];
    const titulo = contexto[contexto.length - 3];

    // Verifica si la modalidad remota se mencionó en las líneas cercanas
    const textoContexto = contexto.join(' ').toLowerCase();
    if ((textoContexto.includes('remoto') || textoContexto.includes('remote')) && !ubicacion.toLowerCase().includes('remot')) {
        ubicacion += ' (Remoto)';
    }

    nuevosJobs.push({
      json: {
        id: `linkedin_${msgId}_${i}`,
        fuente: 'LinkedIn Email',
        titulo,
        empresa,
        url,
        ubicacion,
        descripcionLimpia: contexto.join(' ')
      }
    });
  }
}

return nuevosJobs;

// 1. Lectura de filtros desde Sheets
const filtros = $('Code in JavaScript').first().json || {};

const limpiar = arr => (arr || [])
  .map(x => String(x).toLowerCase().trim())
  .filter(x => x.length > 0);

const rolesDeseados = limpiar(filtros.rolesDeseados);
const rolesRechazados = limpiar(filtros.rolesRechazados);
const keywordsRechazadas = limpiar(filtros.keywordsRechazadas);
const ubicacionesValidas = limpiar(filtros.ubicacionesValidas);
const ubicacionesRechazadas = limpiar(filtros.ubicacionesRechazadas);

// Si la lista no llegó de Sheets, paramos para evitar falsos positivos
if (rolesDeseados.length === 0) {
  return [{
    json: {
      ALERTA: "rolesDeseados llegó vacío. Haz clic en 'Test step' en el nodo 'Code in JavaScript' primero.",
      filtrosRecibidos: filtros
    }
  }];
}

const items = $input.all();
const aprobados = [];

function escapeRegex(str) {
  return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function coincide(patron, texto) {
  if (!patron || !texto) return false;
  if (patron.includes(' ')) {
    return texto.includes(patron);
  }
  return new RegExp(`\\b${escapeRegex(patron)}\\b`, 'i').test(texto);
}

for (const item of items) {
  const job = item.json;

  const titulo = (job.titulo || job.title || job.jobTitle || job.name || '').toLowerCase();
  const descripcion = (job.descripcionLimpia || job.description || job.jobDescription || job.contents || '').toLowerCase();
  const ubicacion = (job.ubicacion || job.candidate_required_location || job.jobGeo || job.locations?.[0]?.name || '').toLowerCase();
  const textoCompleto = `${titulo} ${descripcion}`;

  if (!titulo && !descripcion) continue;

  // 1. Descarte por ubicación rechazada
  if (ubicacionesRechazadas.length > 0) {
    const esVetada = ubicacionesRechazadas.some(ub => coincide(ub, ubicacion));
    if (esVetada) continue;
  }

  // 2. Filtro por ubicación válida
  if (ubicacionesValidas.length > 0) {
    const esValida = ubicacionesValidas.some(ub => coincide(ub, ubicacion));
    if (!esValida) continue;
  }

  // 3. Descarte por rol no deseado en el título (senior, lead, etc.)
  if (rolesRechazados.length > 0) {
    const tieneRolRechazado = rolesRechazados.some(rol => coincide(rol, titulo));
    if (tieneRolRechazado) continue;
  }

  // 4. Descarte por keyword rechazada en el texto (3+ years, etc.)
  if (keywordsRechazadas.length > 0) {
    const tieneKeywordRechazada = keywordsRechazadas.some(kw => coincide(kw, textoCompleto));
    if (tieneKeywordRechazada) continue;
  }

// 5. EVALUACIÓN FLEXIBLE: Buscar rol en el texto completo (título + descripción)
  const rolCoincidente = rolesDeseados.find(rol => coincide(rol, textoCompleto));
  if (!rolCoincidente) {
    continue;
  }

  // Aprobado
  aprobados.push({
    json: {
      id: job.id || Math.random().toString(36).substring(7),
      fuente: job.fuente || 'API',
      titulo: job.titulo || job.title || job.jobTitle || job.name,
      empresa: job.empresa || job.company_name || job.companyName || job.company?.name || 'Confidencial',
      url: job.url || job.refs?.landing_page || '',
      ubicacion: job.ubicacion || job.candidate_required_location || job.jobGeo || 'No especificada',
      motivo_aprobacion: `Coincide con rol deseado: '${rolCoincidente}' en el título`,
      descripcionLimpia: (descripcion || '').replace(/<[^>]*>?/gm, ' ').replace(/\s+/g, ' ').trim().slice(0, 2000)
    }
  });
}


return aprobados;

